@@ -0,0 +1,25 @@
+package wordpress
+
+import (
+	"reflect"
+	"testing"
+
+	"github.com/future-architect/vuls/models"
+)
+
+func TestRemoveInactives(t *testing.T) {
+	packages := models.WordPressPackages{
+		{Name: "active", Status: "active"},
+		{Name: "inactive", Status: models.Inactive},
+		{Name: "must-use", Status: "must-use"},
+		{Name: "unknown", Status: "Inactive"},
+	}
+	want := models.WordPressPackages{packages[0], packages[2], packages[3]}
+	if got := removeInactives(packages); !reflect.DeepEqual(got, want) {
+		t.Errorf("removeInactives() = %#v, want %#v", got, want)
+	}
+
+	if got := removeInactives(models.WordPressPackages{packages[1]}); got != nil {
+		t.Errorf("removeInactives(all inactive) = %#v, want nil", got)
+	}
+}

